import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { t } from './api';
const href = notification => {
  const data = notification.content() || {};
  return app.route('story-chain.story', {
    id: `${data.story ?? ''}-${data.slug ?? ''}`
  });
};

/** To the writer: their line won a round. */
export class WonNotification extends Notification {
  icon() {
    return 'fas fa-feather-pointed';
  }
  href() {
    return href(this.attrs.notification);
  }
  content() {
    const data = this.attrs.notification.content() || {};
    return t(data.finished ? 'notification.won_final' : 'notification.won', {
      title: data.title,
      round: data.round
    });
  }
  excerpt() {
    return null;
  }
}

/** To everyone taking part: a line was added and the next round is open, or the story is finished. */
export class RoundNotification extends Notification {
  icon() {
    return 'fas fa-book-open';
  }
  href() {
    return href(this.attrs.notification);
  }
  content() {
    const notification = this.attrs.notification;
    const data = notification.content() || {};
    if (data.finished) return t('notification.finished', {
      title: data.title
    });
    return t('notification.round', {
      username: notification.fromUser()?.displayName(),
      title: data.title,
      round: data.round
    });
  }
  excerpt() {
    return null;
  }
}